def canonical_json_bytes(value):
    return (json.dumps(value, sort_keys=True, separators=(",", ":"), ensure_ascii=False, allow_nan=False) + "\n").encode("utf-8")

def write_text(path: Path, text: str) -> None:
    path.write_text(text.replace("\r\n", "\n").replace("\r", "\n"), encoding="utf-8", newline="\n")

def replace_one(text: str, old: str, new: str, label: str) -> str:
    count = text.count(old)
    if count != 1:
        raise SystemExit(f"{label}: expected one predecessor, observed {count}")
    return text.replace(old, new, 1)

def replace_regex(text: str, pattern: str, replacement: str, label: str, flags: int = 0) -> str:
    result, count = re.subn(pattern, replacement, text, count=1, flags=flags)
    if count != 1:
        raise SystemExit(f"{label}: expected one regex predecessor, observed {count}")
    return result

def insert_override(path: Path, specific: str) -> None:
    text = path.read_text(encoding="utf-8")
    if "JOIN v2 private-proof and single-campaign closure." in text:
        raise SystemExit(f"override already present in {path}")
    text = replace_regex(
        text,
        r'^CLAIM_BOUNDARY = .+$',
        "CLAIM_BOUNDARY = " + repr(NEW_CLAIM_BOUNDARY),
        f"claim boundary {path.name}",
        re.MULTILINE,
    )
    marker = 'if __name__ == "__main__": raise SystemExit(main())'
    text = replace_one(text, marker, CORE_OVERRIDE + "\n\n" + specific + "\n\n" + marker, f"main guard {path.name}")
    write_text(path, text)

